const delay = 100;     // requested interval (ms)
const work = 7;        // ms the callback body burns each tick
const overhead = 4;    // ms clamp/dispatch overhead added each tick
const ticks = 20;

let chained = 0;       // wall-clock when the chained-setTimeout tick fires
for (let i = 0; i < ticks; i++) {
  // each chained tick fires `delay + work + overhead` after the previous one
  chained += delay + work + overhead;
}
const ideal = ticks * delay;   // an absolute clock-driven schedule never drifts
const drift = chained - ideal;
console.log('drift=' + drift);
